private int _processed;

public void OnMessage()
{
    _processed++; // race: two threads can read same value
}

// Fix:
public void OnMessageSafe() => Interlocked.Increment(ref _processed);

// Thread 1: lock(a) then lock(b)
// Thread 2: lock(b) then lock(a)  // deadlock possible

// Fix: always lock in same order — e.g. by hash code
object first = ReferenceEquals(a, b) ? a : (RuntimeHelpers.GetHashCode(a) < RuntimeHelpers.GetHashCode(b) ? a : b);

